local TaskCellNodePath = 'Game.Activity.BeginnerAssemble.Cell.BeginnerAssembleWelfareCell'

---@type BeginnerUtils
local BeginnerUtils = import('Game.Activity.BeginnerAssemble.BeginnerUtils')

--- from: Assets/BundleResources/Prefabs/BeginnerAssemble/BeginnerAssembleWelfareDialog.prefab > name: BeginnerAssembleWelfareDialog
---@class BeginnerAssembleWelfareDialog
---@field Env                            BeginnerAssembleWelfareDialog
---@field controller                        Engine.Modules.LuaBehaviour
---@field TimeText                        UnityEngine.RectTransform                @ 0
---@field ScrollView                        SuperScrollView.LoopListView2            @ 1
---@field TextTime2                        UnityEngine.RectTransform                @ 2
local BeginnerAssembleWelfareDialog = Class('BeginnerAssembleWelfareDialog')

function BeginnerAssembleWelfareDialog:__init()

end

function BeginnerAssembleWelfareDialog:__delete()

end

function BeginnerAssembleWelfareDialog:Awake()

end

function BeginnerAssembleWelfareDialog:Refresh(config)
    self.config = config
    CfUtils.FillText(self.TimeText, localize('每日5点刷新'))
    ---@type BeginnerMgr
    local beginnerMgr = BeginnerUtils.GetBeginnerMgr()
    ---@type BeginnerDojo
    local dojo = beginnerMgr:GetHomeDojo()
    self.tasks = dojo.dailyTasks
    self:ReloadData()
end

function BeginnerAssembleWelfareDialog:RefreshTopGoods()
    CfUtils.RefreshTopGoods({})
end

function BeginnerAssembleWelfareDialog:RefreshTimeShow()
    local curTime = GameUtils.GetServerTime() or os.time()
    ---@type BeginnerDojo
    local dojo = BeginnerUtils.GetBeginnerMgr():GetHomeDojo()
    local time = math.max(0, dojo.benefitLeftSeconds - curTime)
    CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS4(time))
end

function BeginnerAssembleWelfareDialog:ReloadData()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self.tasks, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, 0)
        GameUtils.ReloadData(self.ScrollView, #self.tasks)
    end
end

function BeginnerAssembleWelfareDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("TaskCell")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
    end
    -- 这里一个cell是一个页面，一个页面有9个按钮
    local data = self.tasks[index + 1]
    if isNotNull(data) then
        ---@type BeginnerAssembleWelfareCell
        local env = CfUtils.GetLuaScr(cell, TaskCellNodePath)
        if env then
            env:SetBtnCallBackGet(Bind(self, self.OnCellAction))
            env:FreshBaseUI(data)
            env:SetBtnCallBackJump(function()
                local isCompleted = data.progress >= data.taskContentNum
                if not isCompleted then
                    if checkNumber(data.openType) == 0 then
                        return
                    end
                    local goodsConfMgr = GoodsConfMgr:GetInstance()
                    local row = goodsConfMgr:GetJumpModuleRow(data.openType)
                    goodsConfMgr:ExecuteJump(row, {})
                end
            end)
        end
    end
    return cell
end

function BeginnerAssembleWelfareDialog:OnCellAction(cellData)
    ---可领取的情况下
    GameUtils.Request(Interfaces.ActivityBeginnerWelfareDraw, { taskId = cellData.id }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local rewards = response.data.rewards
            GoodsUtils.DrawRewards(rewards, true)
            ---更新界面ui
            ---@type BeginnerMgr
            local beginnerMgr = BeginnerUtils.GetBeginnerMgr()
            ---@type BeginnerDojo
            local dojo = beginnerMgr:GetHomeDojo()
            for i, v in pairs(dojo.dailyTasks) do
                if checkNumber(v.id) == checkNumber(cellData.id) then
                    v.hasDrawn = 1
                    v.progress = math.max(v.taskContentNum, v.progress)
                end
            end
            ----已领取的逻辑
            CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
            BeginnerUtils.RefreshRedPoint(self.config.type)
            self:Refresh(self.config)
        end
    end)
end
function BeginnerAssembleWelfareDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return BeginnerAssembleWelfareDialog